FUNCTION_BLOCK FB_Ventilador
VAR
    quemadorOn : BOOL; // Variable de entrada: estado del quemador
    ventilador : BOOL; // Variable de salida: estado del ventilador
    timer : TON; // Temporizador para controlar el tiempo de enfriamiento
END_VAR

// Inicialización del temporizador
timer(IN := FALSE, PT := T#30S);

IF quemadorOn THEN
    // Si el quemador está encendido, el ventilador debe estar encendido
    ventilador := TRUE;
    timer(IN := FALSE); // Asegurarse de que el temporizador esté apagado
ELSE
    // Si el quemador está apagado, iniciar el temporizador
    timer(IN := TRUE);
    IF timer.Q THEN
        // Si el temporizador ha terminado, apagar el ventilador
        ventilador := FALSE;
    ELSE
        // Mientras el temporizador no haya terminado, mantener el ventilador encendido
        ventilador := TRUE;
    END_IF
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Ventilador
VAR_INPUT
    quemadorOn : BOOL; // Indica si el quemador está encendido
END_VAR

VAR_OUTPUT
    ventilador : BOOL; // Comando de encendido para el ventilador
END_VAR

VAR
    temporizadorTOF : TOF; // Temporizador de retardo a la desconexión (Off-Delay)
END_VAR

// Configuración y ejecución del temporizador
// Si quemadorOn es TRUE, la salida Q es TRUE inmediatamente.
// Cuando quemadorOn pasa a FALSE, Q se mantiene TRUE durante el tiempo PT (30s) y luego pasa a FALSE.
temporizadorTOF(IN := quemadorOn, PT := T#30S);

// Asignación del estado del temporizador a la salida del ventilador
ventilador := temporizadorTOF.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Ventilador
VAR_INPUT
    quemadorOn : BOOL; // Estado del quemador (TRUE si encendido, FALSE si apagado)
END_VAR

VAR_OUTPUT
    ventilador : BOOL; // Estado del ventilador (TRUE si encendido, FALSE si apagado)
END_VAR

VAR
    timer : TON; // Timer de retardo
    timerDone : BOOL; // Bandera para indicar si el timer ha terminado
END_VAR

// Inicialización del timer
IF NOT timerDone THEN
    timer(IN := NOT quemadorOn, PT := T#30S);
    timerDone := timer.Q;
END_IF;

// Control del ventilador
IF quemadorOn OR (NOT quemadorOn AND NOT timerDone) THEN
    ventilador := TRUE;
ELSE
    ventilador := FALSE;
END_IF;

FUNCTION_BLOCK FB_Ventilador
VAR
    // Variable de entrada: estado del quemador
    quemadorOn : BOOL;

    // Variable de salida: estado del ventilador
    ventilador : BOOL;

    // Temporizador para controlar el tiempo adicional de funcionamiento del ventilador
    timer : TON;
END_VAR

// Inicialización del temporizador con un tiempo de 30 segundos
timer(IN := NOT quemadorOn, PT := T#30S);

// Lógica para controlar el ventilador
IF quemadorOn THEN
    // Si el quemador está encendido, el ventilador también debe estar encendido
    ventilador := TRUE;
ELSE
    // Si el quemador está apagado, el ventilador sigue encendido hasta que el temporizador expire
    ventilador := NOT timer.Q;
END_IF;

// Actualización del temporizador
timer(IN := NOT quemadorOn);

FUNCTION_BLOCK FB_Ventilador
VAR_INPUT
    quemadorOn : BOOL; // Indica si el quemador está encendido
END_VAR
VAR_OUTPUT
    ventilador : BOOL; // Controla el estado del ventilador
END_VAR
VAR
    temporizadorTOF : TOF; // Temporizador de retardo a la desconexión (Off-Delay)
END_VAR

// El temporizador TOF mantiene su salida Q en TRUE mientras IN sea TRUE, 
// y la mantiene 30 segundos adicionales después de que IN pase a FALSE.
temporizadorTOF(IN := quemadorOn, PT := T#30S);

// Asignación directa de la salida del temporizador al ventilador
ventilador := temporizadorTOF.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Ventilador
VAR_INPUT
    quemadorOn : BOOL; // Indica si el quemador está encendido
END_VAR
VAR_OUTPUT
    ventilador : BOOL; // Controla el estado del ventilador
END_VAR
VAR
    timerTOF : TOF; // Temporizador de retardo a la desconexión (Off-Delay)
END_VAR

// Llamada al temporizador: 
// Mientras IN es TRUE, Q es TRUE. 
// Cuando IN pasa a FALSE, Q se mantiene TRUE durante el tiempo PT (30s) y luego pasa a FALSE.
timerTOF(IN := quemadorOn, PT := T#30S);

// Asignación de la salida del temporizador al ventilador
ventilador := timerTOF.Q;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Ventilador
VAR_INPUT
    quemadorOn : BOOL; // Indica si el quemador está encendido
END_VAR

VAR_OUTPUT
    ventilador : BOOL; // Controla el ventilador
END_VAR

VAR
    timer : TON; // Timer de retardo
    timerDone : BOOL; // Indica si el timer ha terminado
END_VAR

// Inicialización del timer
IF NOT timerDone THEN
    timer(IN := NOT quemadorOn, PT := T#30S);
    timerDone := timer.Q;
END_IF;

// Control del ventilador
IF quemadorOn OR NOT timerDone THEN
    ventilador := TRUE;
ELSE
    ventilador := FALSE;
END_IF;

FUNCTION_BLOCK FB_Ventilador
VAR
    // Variable de entrada
    quemadorOn : BOOL; // Estado del quemador: TRUE si está encendido, FALSE si está apagado

    // Variable de salida
    ventilador : BOOL; // Estado del ventilador: TRUE si está encendido, FALSE si está apagado

    // Variables internas
    timer : TON; // Temporizador para controlar el tiempo adicional de funcionamiento del ventilador
END_VAR

// Lógica del ventilador
IF quemadorOn THEN
    // Si el quemador está encendido, el ventilador debe estar encendido
    ventilador := TRUE;
    // Reiniciar el temporizador
    timer(IN := FALSE);
ELSE
    // Si el quemador está apagado, iniciar el temporizador
    timer(IN := TRUE, PT := T#30S);
    // El ventilador sigue encendido mientras el temporizador no haya alcanzado el tiempo establecido
    ventilador := timer.Q;
END_IF
END_FUNCTION_BLOCK
